.jui-all-set {
  --all-set-ink: #191414;
  --all-set-paper: #ffffff;
  --all-set-step: 42ms;
  position: relative;
  isolation: isolate;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: clamp(28px, 6vh, 48px);
  min-height: 100%;
  width: 100%;
  padding: 48px 24px 64px;
  overflow: hidden;
  background: var(--all-set-paper);
  color: var(--all-set-ink);
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
}

.jui-all-set-burst {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.jui-all-set-title {
  position: relative;
  z-index: 1;
  margin: 0;
  max-width: 12ch;
  color: var(--all-set-ink);
  font-size: clamp(44px, 8vw, 92px);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  text-align: center;
  text-wrap: balance;
}

.jui-all-set-letter {
  display: inline-block;
  animation: jui-all-set-in 520ms cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(var(--i) * var(--all-set-step));
}

.jui-all-set-action {
  position: relative;
  z-index: 1;
  border: 0;
  border-radius: 999px;
  padding: 16px 32px;
  background: var(--all-set-ink);
  color: var(--all-set-paper);
  font: inherit;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1;
  text-transform: uppercase;
  cursor: pointer;
  opacity: 0;
  transform: translateY(10px);
  animation: jui-all-set-action 480ms cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc((var(--all-set-count) - 1) * var(--all-set-step) + 180ms);
}

.jui-all-set-action:hover {
  transform: scale(1.04);
}

.jui-all-set-action:active {
  transform: scale(0.98);
}

.jui-all-set-action:focus-visible {
  outline: 2px solid var(--all-set-ink);
  outline-offset: 4px;
}

@keyframes jui-all-set-in {
  from {
    opacity: 0;
    transform: translateX(-0.35em);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes jui-all-set-action {
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .jui-all-set-letter,
  .jui-all-set-action {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
} from "react";
import confetti from "canvas-confetti";
import { useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";
import "./all-set.css";


export type AllSetProps = Omit<ComponentProps<"section">, "title"> & {
  title?: string;
  actionLabel?: string;
  replayKey?: string | number;
  onAction?: () => void;
};

const palette = ["#1ed760", "#1db954", "#191414", "#b3b3b3", "#ffffff", "#535353"];

export function AllSet({
  title = "You're all set",
  actionLabel = "Open Spotify",
  replayKey,
  onAction,
  className,
  ...props
}: AllSetProps) {
  return (
    <AllSetRun
      key={replayKey}
      title={title}
      actionLabel={actionLabel}
      onAction={onAction}
      className={className}
      {...props}
    />
  );
}

function AllSetRun({
  title = "You're all set",
  actionLabel = "Open Spotify",
  onAction,
  className,
  style,
  ...props
}: AllSetProps) {
  const reduced = useReducedMotion();
  const letters = [...title];
  const stage = useRef<HTMLElement>(null);
  const burst = useRef<ReturnType<typeof confetti.create> | null>(null);
  const timers = useRef<number[]>([]);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const canvas = stage.current?.querySelector("canvas");
    if (!(canvas instanceof HTMLCanvasElement)) return;
    const fit = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const width = parent.clientWidth;
      const height = parent.clientHeight;
      const ratio = window.devicePixelRatio || 1;
      canvas.width = Math.max(1, Math.floor(width * ratio));
      canvas.height = Math.max(1, Math.floor(height * ratio));
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(canvas.parentElement!);
    const shoot = confetti.create(canvas, { resize: false, useWorker: false });
    burst.current = shoot;
    const clear = () => {
      timers.current.forEach((id) => window.clearTimeout(id));
      timers.current = [];
      shoot.reset();
    };
    if (reduced) {
      return () => {
        clear();
        observer.disconnect();
      };
    }
    const fire = (options: confetti.Options) => {
      void shoot({
        colors: palette,
        disableForReducedMotion: true,
        ...options,
      });
    };
    const cheer = () => {
      fire({
        particleCount: 90,
        spread: 70,
        startVelocity: 48,
        origin: { x: 0.5, y: 0.72 },
        scalar: 0.9,
      });
      fire({
        particleCount: 36,
        angle: 60,
        spread: 55,
        startVelocity: 55,
        origin: { x: 0, y: 0.65 },
      });
      fire({
        particleCount: 36,
        angle: 120,
        spread: 55,
        startVelocity: 55,
        origin: { x: 1, y: 0.65 },
      });
    };
    cheer();
    timers.current.push(window.setTimeout(cheer, 280));
    return () => {
      clear();
      observer.disconnect();
    };
  }, [reduced]);

  useEffect(() => {
    const delay = reduced ? 0 : Math.max(0, letters.length - 1) * 42 + 420;
    const id = window.setTimeout(() => setReady(true), delay);
    return () => window.clearTimeout(id);
  }, [letters.length, reduced]);

  return (
    <section
      {...props}
      ref={stage}
      data-slot="all-set"
      data-ready={ready || undefined}
      className={cn("jui-all-set", className)}
      style={{ "--all-set-count": letters.length, ...style } as CSSProperties}
    >
      <canvas className="jui-all-set-burst" aria-hidden="true" />
      <h1 className="jui-all-set-title">
        {letters.map((letter, index) => (
          <span
            key={`${letter}-${index}`}
            className="jui-all-set-letter"
            style={{ "--i": index } as CSSProperties}
          >
            {letter === " " ? "\u00a0" : letter}
          </span>
        ))}
      </h1>
      <button
        type="button"
        className="jui-all-set-action"
        onClick={() => {
          burst.current?.reset();
          onAction?.();
        }}
      >
        {actionLabel}
      </button>
    </section>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
